import { GEO } from './bcn-geodata.js';

// Barcelona spatial configuration & street database at true 1:1 scale, derived from the real geography in
// js/bcn-geodata.js (generated by tools/build-bcn-geodata.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = Eixample-grid east (along Carrer d'Aragó toward the Besòs), z = grid south (down
// Passeig de Gràcia toward the sea), so north = -z climbs toward Collserola. Origin at the centre of Plaça de Catalunya;
// the axes are turned ~45° from true north like Cerdà's grid itself. The detailed city runs from Sants & Plaça
// d'Espanya to Poblenou and from the foot of Gràcia to the sea (GEO.frame.detail); the metropolitan area around it is
// low-detail (boroughs.js).

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};

// Geographic frame, for the maps' compass and anything placed from latitude & longitude
const FRAME = (() => {
  const { lat0, lon0, kx, ky, bearingDeg } = GEO.frame;
  return { lat0, lon0, kx, ky, th: (bearingDeg * Math.PI) / 180 };
})();
/** World (x, z) of a latitude & longitude */
function lonLatToWorld(lon, lat) {
  const e = (lon - FRAME.lon0) * FRAME.kx;
  const n = (lat - FRAME.lat0) * FRAME.ky;
  const c = Math.cos(FRAME.th);
  const s = Math.sin(FRAME.th);
  return { x: e * c - n * s, z: -(e * s + n * c) };
}

// ---------------------------------------------------------------------------------------------------------------------
// The city's grid: Barcelona has no numbered streets or avenues on fixed lines for road-network.js to build grid
// corridors from (every street is a centreline in ROADS and the road graph); and no park takes a whole district: its
// bounds are a 1 m box far out at sea that nothing falls inside (finite, as the shaders read it)
// ---------------------------------------------------------------------------------------------------------------------
const ALL_AVENUES = [];
const ALL_STREETS = [];
const CENTRAL_PARK_BOUNDS = { minX: 90000, maxX: 90001, minZ: 90000, maxZ: 90001 };

// ---------------------------------------------------------------------------------------------------------------------
// Shoreline: the detailed city's land (the coast from Montjuïc's port to Poblenou's beaches, and the rectangle's edges
// inland); west / east edge x at any z
// ---------------------------------------------------------------------------------------------------------------------
const COASTLINE = toPts(GEO.land);
// The detailed city's grid rectangle (its land is COASTLINE)
const GEO_FRAME_DETAIL = GEO.frame.detail;
const METRO_LAND = toPts(GEO.metroLand);
const SHORE = (() => {
  const step = 2;
  let z0 = Infinity;
  let z1 = -Infinity;
  for (const p of COASTLINE) {
    z0 = Math.min(z0, p.z);
    z1 = Math.max(z1, p.z);
  }
  z0 = Math.ceil(z0 / step) * step;
  const n = Math.floor((z1 - z0) / step) + 1;
  const west = new Float32Array(n).fill(NaN);
  const east = new Float32Array(n).fill(NaN);
  const P = COASTLINE;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const a = P[j];
    const b = P[i];
    if (a.z === b.z) continue;
    const lo = Math.min(a.z, b.z);
    const hi = Math.max(a.z, b.z);
    for (let k = Math.max(0, Math.ceil((lo - z0) / step)); k < n && z0 + k * step < hi; k++) {
      const z = z0 + k * step + 1e-3;
      if (z < lo || z >= hi) continue;
      const x = a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z);
      if (!(west[k] <= x)) west[k] = x;
      if (!(east[k] >= x)) east[k] = x;
    }
  }
  for (let k = 1; k < n; k++) if (Number.isNaN(west[k])) { west[k] = west[k - 1]; east[k] = east[k - 1]; }
  for (let k = n - 2; k >= 0; k--) if (Number.isNaN(west[k])) { west[k] = west[k + 1]; east[k] = east[k + 1]; }
  return { z0, step, n, west, east, z1 };
})();

/** West / east edge x of the detailed land at a given z (the outermost crossings), clamped at its ends */
function getIslandBoundsAtZ(z) {
  const f = (z - SHORE.z0) / SHORE.step;
  const k = Math.max(0, Math.min(SHORE.n - 2, Math.floor(f)));
  const t = Math.max(0, Math.min(1, f - k));
  return {
    westX: SHORE.west[k] + (SHORE.west[k + 1] - SHORE.west[k]) * t,
    eastX: SHORE.east[k] + (SHORE.east[k + 1] - SHORE.east[k]) * t
  };
}

function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}

// Land cells (32 m) of the detailed city, for quick on-land tests (traffic, pedestrians, the maps)
const LAND_CELL = 32;
const LAND_GRID = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of COASTLINE) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  const x0 = Math.floor(minX / LAND_CELL), z0 = Math.floor(minZ / LAND_CELL);
  const w = Math.ceil(maxX / LAND_CELL) - x0 + 1, h = Math.ceil(maxZ / LAND_CELL) - z0 + 1;
  const cells = new Uint8Array(w * h);
  for (let j = 0; j < h; j++) {
    for (let i = 0; i < w; i++) {
      const cx = (x0 + i + 0.5) * LAND_CELL, cz = (z0 + j + 0.5) * LAND_CELL;
      cells[j * w + i] = pointInPoly(COASTLINE, cx, cz) ? 1 : 0;
    }
  }
  return { x0, z0, w, h, cells };
})();
/** Is (x, z) on the detailed city's land? */
function onLand(x, z) {
  const i = Math.floor(x / LAND_CELL) - LAND_GRID.x0, j = Math.floor(z / LAND_CELL) - LAND_GRID.z0;
  if (i < 0 || j < 0 || i >= LAND_GRID.w || j >= LAND_GRID.h) return false;
  const c = LAND_GRID.cells[j * LAND_GRID.w + i];
  // cells on the shore are tested exactly
  const edge = i === 0 || j === 0 || i === LAND_GRID.w - 1 || j === LAND_GRID.h - 1 ||
    LAND_GRID.cells[j * LAND_GRID.w + i - 1] !== c || LAND_GRID.cells[j * LAND_GRID.w + i + 1] !== c ||
    LAND_GRID.cells[(j - 1) * LAND_GRID.w + i] !== c || LAND_GRID.cells[(j + 1) * LAND_GRID.w + i] !== c;
  return edge ? pointInPoly(COASTLINE, x, z) : !!c;
}

// ---------------------------------------------------------------------------------------------------------------------
// Streets database: every named street (the real centreline, merged per name) — maps, labels & lookups
// ---------------------------------------------------------------------------------------------------------------------
// Short forms for labels: "Carrer de Mallorca" -> "C. Mallorca", "Passeig de Gràcia" -> "Pg. Gràcia"
const PREFIX = [
  [/^Carrer (de la |de l'|del |dels |de les |de |d'|)/, 'C. '], [/^Passeig (de la |de l'|del |dels |de |d'|)/, 'Pg. '],
  [/^Avinguda (de la |de l'|del |dels |de |d'|)/, 'Av. '], [/^Plaça (de la |de l'|del |dels |de |d'|)/, 'Pl. '],
  [/^Rambla (de la |de l'|del |dels |de |d'|)/, 'Rbla. '], [/^Ronda (de la |de l'|del |dels |de |d'|)/, 'Rda. '],
  [/^Via (de la |de l'|del |dels |de |d'|)/, 'Via '], [/^Gran Via de les Corts Catalanes$/, 'Gran Via'], [/^Baixada (de la |de l'|del |de |d'|)/, 'Bda. '],
  [/^Travessera (de la |de l'|del |de |d'|)/, 'Trav. '], [/^Passatge (de la |de l'|del |dels |de |d'|)/, 'Ptge. ']
];
function shortName(name) {
  for (const [re, abbr] of PREFIX) {
    if (re.test(name)) {
      const s = name.replace(re, abbr);
      return s === 'Gran Via' ? s : s.charAt(0).toUpperCase() + s.slice(1);
    }
  }
  return name;
}
const ROADS = GEO.roads.map(([name, w, dir, lanes, ped, flat]) => ({ name, short: shortName(name), raw: name, w, dir, lanes, highway: false, pedestrian: !!ped, pts: toPts(flat) }));

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist, horizontal }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz) });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island (raised sidewalk slab) with its lot rectangles inside the building line
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots (axis-aligned), park: share covered by
//   parkland, parkName (the park, square or beach's name), rect: the island is an axis-aligned rectangle,
//   frames: irregular islands' lots laid out along the streets they front, [[θ, px, pz, rects], ...] (rects in a
//   frame turned by θ about (px, pz): world = p + R_y(θ)·(local − p)), or null; beach & square shares; storeys: the
//   area-weighted median & 95th percentile of its buildings' storeys in OpenStreetMap (0 when unknown); illa: an
//   Eixample block's building-line square & chamfer legs [x0, x1, z0, z1, c] (its lots are laid out by buildings.js)
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames, beach, square, med, p95, illa], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  // squares & beaches are open ground like parks: no lots
  const open = park + square + beach;
  return {
    id, poly, rects, frames: frames || null, park: open > 0.6 ? Math.max(park, 0.61) : park, parkName, rect: !!isRect, area,
    beach, square, storeys: [med, p95], illa: illa || null,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: Math.min(maxX - minX, maxZ - minZ) < 9 || (area < 1500 && Math.min(maxX - minX, maxZ - minZ) < 14 && !rects.length && !frames)
  };
});
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
/** The block (curb island) under (x, z), or null on the roadway / in the water */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods (barris) by position in the grid frame, for building profiles, labels & the maps
// ---------------------------------------------------------------------------------------------------------------------
const P = Object.fromEntries(Object.entries(GEO.points).map(([k, [x, z]]) => [k, { x, z }]));
// The old town's walls ran where the Rondes and Paral·lel are now: south of a line from Plaça Universitat through
// Plaça de Catalunya to the Arc de Triomf, between Paral·lel and Ciutadella
function inCiutatVella(x, z) {
  const north = (x2) => (x2 < P.placaCatalunya.x ? 140 + (P.placaCatalunya.x - x2) * 0.08 : 140 - (x2 - P.placaCatalunya.x) * 0.06);
  return z > north(x) && x > -1050 + (z - 400) * 0.35 && x < 900 && z < 1500;
}
function districtAt(x, z) {
  if (x < -1300 && z > 350) return 'montjuic';
  if (x < -2250) return 'sants';
  if (z > 1450 && x < 1250) return x < -350 ? 'port' : 'barceloneta';
  if (inCiutatVella(x, z)) {
    if (x < P.liceu.x - 40) return 'raval';
    if (x > P.santaMariaMar.x - 260) return 'born';
    return 'gotic';
  }
  if (x < -1050 && z > 150) return 'poble_sec';
  if (x > 1300 && z > 800) return x > 2300 ? 'poblenou' : 'vila_olimpica';
  if (x > 2600) return 'poblenou';
  if (z < -1350 && x > -900 && x < 1400) return 'gracia';
  if (z < -1450) return 'sant_gervasi';
  if (x > 1800 && z < -300) return 'glories';
  if (x < -1500) return 'sant_antoni';
  return 'eixample';
}
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);
const DISTRICT_NAMES = {
  montjuic: 'Montjuïc', sants: 'Sants', port: 'Port Vell', barceloneta: 'La Barceloneta', raval: 'El Raval', born: 'El Born',
  gotic: 'Barri Gòtic', poble_sec: 'Poble-sec', vila_olimpica: 'Vila Olímpica', poblenou: 'Poblenou', gracia: 'Gràcia',
  sant_gervasi: 'Sant Gervasi', glories: 'Glòries', sant_antoni: 'Sant Antoni', eixample: "L'Eixample"
};

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap: centre, grid-aligned width x depth, height) & teleports
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
const heading = (from, to) => Math.atan2(to.x - from.x, to.z - from.z);
// The nearest point on the centreline of a street at least `minWidth` wide (curb to curb) within 120 m of (x, z)
function snapToStreet(x, z, minWidth = 7) {
  let best = null;
  for (const { road } of nearestRoads(x, z, 120)) {
    if (road.pedestrian || road.w < minWidth) continue;
    for (let i = 0; i + 1 < road.pts.length; i++) {
      const a = road.pts[i];
      const b = road.pts[i + 1];
      const dx = b.x - a.x, dz = b.z - a.z;
      const t = Math.max(0, Math.min(1, ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz || 1)));
      const px = a.x + dx * t, pz = a.z + dz * t;
      const d = Math.hypot(px - x, pz - z);
      if (!best || d < best.d) best = { d, x: px, z: pz };
    }
  }
  return best ? { x: best.x, z: best.z } : { x, z };
}
// Street-level arrivals shared by every travel mode: on the street nearest a point a little way off each sight, facing
// it. Heading 0 faces grid south (+z, toward the sea), PI grid north.
const arrival = (to, dx, dz) => {
  const at = snapToStreet(to.x + dx, to.z + dz);
  return { ...at, heading: heading(at, to) };
};
const TELEPORT_LOCATIONS = {
  sagrada: arrival(P.sagradaFamilia, -40, 150),
  catalunya: arrival(P.placaCatalunya, 0, -150),
  batllo: arrival(P.casaBatllo, -60, 70),
  pedrera: arrival(P.pedrera, -60, 80),
  arc: arrival(P.arcTriomf, 40, 150),
  rambla: arrival(P.liceu, -30, -100),
  glories: arrival(P.torreGlories, -160, 100),
  colom: arrival(P.colom, 0, -110),
  barceloneta: arrival(P.barceloneta, -90, -80),
  vela: arrival(P.hotelW, 40, -260)
};
// Where every travel mode starts on a first visit: Passeig de Gràcia's southbound roadway by Casa Batlló, facing down
// toward Plaça de Catalunya
const SPAWN = (() => {
  const pg = ROADS.filter((r) => r.name === 'Passeig de Gràcia').flatMap((r) => r.pts);
  const target = { x: P.casaBatllo.x, z: P.casaBatllo.z + 90 };
  const at = pg.reduce((a, p) => (Math.hypot(p.x - target.x, p.z - target.z) < Math.hypot(a.x - target.x, a.z - target.z) ? p : a), pg[0] || target);
  return { x: at.x - 5, z: at.z, heading: 0 };
})();
const CITY_LANDMARKS = [
  ['sagrada', 'Sagrada Família', 'Sagrada Família', P.sagradaFamilia, "L'Eixample"],
  ['catalunya', 'Plaça de Catalunya', 'Pl. Catalunya', P.placaCatalunya, 'Centre'],
  ['batllo', 'Casa Batlló', 'Casa Batlló', P.casaBatllo, 'Passeig de Gràcia'],
  ['pedrera', 'La Pedrera (Casa Milà)', 'La Pedrera', P.pedrera, 'Passeig de Gràcia'],
  ['arc', 'Arc de Triomf', 'Arc de Triomf', P.arcTriomf, 'Passeig de Lluís Companys'],
  ['rambla', 'La Rambla & el Liceu', 'La Rambla', P.liceu, 'Ciutat Vella'],
  ['catedral', 'Catedral de Barcelona', 'Catedral', P.catedral, 'Barri Gòtic'],
  ['ciutadella', 'Parc de la Ciutadella', 'Ciutadella', P.ciutadella, 'Ciutat Vella'],
  ['glories', 'Torre Glòries', 'Torre Glòries', P.torreGlories, 'Sant Martí'],
  ['colom', 'Monument a Colom', 'Colom', P.colom, 'Port Vell'],
  ['barceloneta', 'Platja de la Barceloneta', 'Barceloneta', P.barceloneta, 'La Barceloneta'],
  ['vela', 'Hotel W (la Vela)', 'Hotel W', P.hotelW, 'Port'],
  ['arts', 'Hotel Arts & Torre Mapfre', 'Hotel Arts', P.hotelArts, 'Vila Olímpica'],
  ['espanya', "Plaça d'Espanya", 'Pl. Espanya', P.placaEspanya, 'Sants-Montjuïc']
].map(([id, name, short, p, district]) => ({ id, name, short, x: p.x, z: p.z, district }));

const ISLAND_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of COASTLINE) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.2 };
})();

/** Street & place name at any world (x, z): the nearest roads of the real street centreline */
function getLocationLabel(x, z) {
  for (const lm of CITY_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) {
      const near = nearestRoads(x, z, 120);
      return `${lm.name}${near.length ? ` · ${near[0].road.short}` : ''}`;
    }
  }
  const b = blockAt(x, z);
  if (b && b.parkName && b.park > 0.6) return b.parkName;
  if (!onLand(x, z)) return METRO_LAND.length && pointInPoly(METRO_LAND, x, z) ? 'Barcelona' : 'Mar Mediterrània';
  const near = nearestRoads(x, z, 160);
  // a corner: the two nearest streets crossing each other
  const a = near[0];
  const c = a && near.find((r) => r.horizontal !== a.horizontal && r.dist < a.dist + 25);
  if (a && c) return `${a.road.short} & ${c.road.short}`;
  if (a) return a.road.name;
  return DISTRICT_NAMES[districtAt(x, z)] || 'Barcelona';
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds:
// the "avenue" phase (traffic along grid x: carrers paral·lels al mar, d'Aragó, Mallorca...) green until avenueAmber,
// amber until avenueRed; the cross phase (along grid z: Balmes, Pau Claris...) green from avenueRed until streetAmber,
// amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off only
// on the green man, the first `walk` seconds of its green.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for avenue or cross street traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside avenue (or cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

